export function sampleStops(g,draw=randomInt){return g.reelStrips.map(strip=>drawIndex(draw,strip.length));}
export function visibleGrid(g,stops){
 check(Array.isArray(stops)&&stops.length===g.reels,'INVALID_STOPS');
 stops.forEach((s,c)=>check(Number.isInteger(s)&&s>=0&&s<g.reelStrips[c].length,'INVALID_STOP'));
 return Array.from({length:g.rows},(_,r)=>g.reelStrips.map((strip,c)=>strip[(stops[c]+r-Math.floor(g.rows/2)+strip.length)%strip.length]));
}
function validGrid(g,grid){check(Array.isArray(grid)&&grid.length===g.rows&&grid.every(row=>Array.isArray(row)&&row.length===g.reels),'BAD_GRID');}
export function evaluatePaylines(g,grid,stakePerLine){
 validGrid(g,grid);const result=[];const isWild=s=>wild(s)||(['hot_foxy_20','foxy_hot_20_native'].includes(g.id)&&s==='fox');
 for(const [index,path] of paths(g).entries()){
  const symbols=path.map((r,c)=>grid[r][c]);if(symbols.slice(0,3).includes('scatter'))continue;
  const candidates=new Set(symbols.filter(s=>!isWild(s)&&s!=='scatter'));
  let prefix=0;while(prefix<symbols.length&&isWild(symbols[prefix]))prefix++;
  if(prefix>=3){let best=null;for(const [id,pays] of Object.entries(g.paytable)){const award=pays[prefix]||0;if(!best||award>best.award)best={id,award};}if(best)candidates.add(best.id);}
  let best=null;
  for(const symbol of candidates){
   const table=g.paytable[symbol];if(!table)continue;let count=0;
   for(const s of symbols){if(s!==symbol&&!isWild(s))break;count++;}
   const factor=table[count];if(count<3||!Number.isInteger(factor)||factor<0)continue;
   const wilds=symbols.slice(0,count).filter(isWild).length;
   const baseUnits=stakePerLine*BigInt(factor)*BigInt(g.features.wildStack?Math.min(8,2**wilds):1);
   const win={line:index+1,rows:path,symbol,count,positions:path.slice(0,count).map((r,c)=>[r,c]),wilds,baseUnits};
   if(!best||baseUnits>best.baseUnits||(baseUnits===best.baseUnits&&count>best.count))best=win;
  }
  if(best)result.push(best);
  if(g.features.bonusPick&&new Set(symbols.slice(0,3).filter(s=>/^tribal_woman_[123]$/.test(s))).size===3)
   result.push({line:index+1,rows:path,symbol:'sister_synergy',count:3,positions:path.slice(0,3).map((r,c)=>[r,c]),wilds:0,baseUnits:stakePerLine*225n/10n});
 }
 return result;
}
export function evaluateGrid(g,grid,stake,wheel,{isFree=false,cascadeStep=0}={}){
 validGrid(g,grid);const lineCount=BigInt(paths(g).length);
 check(stake>0n&&stake%lineCount===0n,'BET_SPLIT_ERROR');check(g.wheel.values.includes(wheel),'WHEEL_VALUE_INVALID');
 check(Number.isInteger(cascadeStep)&&cascadeStep>=0,'INVALID_CASCADE_STEP');
 const wins=evaluatePaylines(g,grid,stake/lineCount),f=g.features;
 const stack=f.maxStackMultiplier?Math.min(f.maxStackMultiplier,wheel*2**Math.max(0,...wins.map(w=>w.wilds))):wheel;
 const cascadeMult=Math.min(cascadeStep+1,6),freeMult=isFree?f.freeSpins.winMultiplier:1;
 const multiplier=BigInt(stack)*BigInt(cascadeMult)*BigInt(freeMult);
 const scatterCount=grid.flat().filter(s=>s==='scatter').length;
 const jackpotMult=Number(f.jackpots[String(Math.min(5,scatterCount))]||0),jackpotUnits=stake*BigInt(jackpotMult);
 const scatterUnits=g.id!=='foxy_hot_20_native'&&!jackpotMult&&scatterCount>=3?stake*BigInt(({3:2,4:10,5:50})[Math.min(5,scatterCount)])*BigInt(wheel):0n;
 const lineWinUnits=wins.reduce((sum,w)=>sum+w.baseUnits*multiplier,0n);
 return {wins:wins.map(({baseUnits,...w})=>({...w,baseWin:fromUnits(baseUnits),win:fromUnits(baseUnits*multiplier)})),lineWinUnits,jackpotUnits,scatterUnits,
  totalUnits:lineWinUnits+jackpotUnits+scatterUnits,stack,cascadeMult,scatterCount,
  bonusSpinsAwarded:scatterCount>=f.freeSpins.trigger&&(!isFree||f.freeSpins.retrigger)?f.freeSpins.spins:0,
  jackpotTier:jackpotMult?({50:'Silver',250:'Gold',10000:'Platinum'})[jackpotMult]:null,
  bonusPickAwarded:Boolean(f.bonusPick&&scatterCount>=3)};
}
export function cascadeGrid(g,grid,wins,draw=randomInt){
 validGrid(g,grid);const removed=new Set(wins.flatMap(w=>w.positions.map(p=>p.join(','))));
 const out=Array.from({length:g.rows},()=>Array(g.reels));
 for(let c=0;c<g.reels;c++){const survivors=[];for(let r=g.rows-1;r>=0;r--)if(!removed.has(`${r},${c}`))survivors.push(grid[r][c]);
  for(let r=g.rows-1;r>=0;r--)out[r][c]=survivors[g.rows-1-r]??g.reelStrips[c][drawIndex(draw,g.reelStrips[c].length)];}
 return out;
}
export function spin(gameId,bet,opts={}){
 const g=getGame(gameId);check((g.betLevels||MATH.betLevels).includes(bet),'BET_LEVEL_NOT_ALLOWED');
 const stake=toUnits(bet),draw=opts.draw||randomInt,stops=sampleStops(g,draw),wheel=weightedWheel(g,draw);
 let grid=visibleGrid(g,stops),total=0n,bonuses=0,bonusPick=false,scatterCount=0,jackpotTier=null;
 const stages=[],cascadeActive=g.features.cascadeLimit>0&&grid.flat().includes('super_wild');
 for(let step=0;step<=g.features.cascadeLimit;step++){
  const o=evaluateGrid(g,grid,stake,wheel,{isFree:!!opts.isFree,cascadeStep:step});
  stages.push({grid,winLines:o.wins,lineWin:fromUnits(o.lineWinUnits),jackpotWin:fromUnits(o.jackpotUnits),scatterWin:fromUnits(o.scatterUnits),win:fromUnits(o.totalUnits),stackMultiplier:o.stack,cascadeMultiplier:o.cascadeMult});
  total+=o.totalUnits;bonuses=Math.max(bonuses,o.bonusSpinsAwarded);scatterCount=Math.max(scatterCount,o.scatterCount);bonusPick||=o.bonusPickAwarded;jackpotTier||=o.jackpotTier;
  if(!cascadeActive||step===g.features.cascadeLimit||!o.wins.length)break;
  grid=cascadeGrid(g,grid,o.wins,draw);
 }
 const cap=stake*BigInt(g.maxWinMultiplier),maxWinCapped=total>cap;const uncappedWin=fromUnits(total);if(maxWinCapped)total=cap;
 return {roundId:randomUUID(),gameId,engineVersion:ENGINE_VERSION,mathVersion:g.mathVersion||MATH.mathVersion,mathSha256,
  grid:stages.at(-1).grid,initialGrid:stages[0].grid,stops,wheelMultiplier:wheel,wheelPosition:g.wheel.position,
  winLines:stages.at(-1).winLines,stages,bet,chargedStake:opts.isFree?'0.0000':fromUnits(stake),isFree:!!opts.isFree,
  finalWin:fromUnits(total),uncappedWin,bonusSpinsAwarded:Math.min(bonuses,100),scatterCount,jackpotTier,pendingBonusPick:bonusPick,
  dragonFire:gameId==='bao_slot_5x'&&stages.some(s=>s.winLines.some(w=>w.symbol==='dragon'&&w.count===5)),maxWinCapped,currency:MATH.currency};
}
export function gambleDraw(choice,stake,draw=randomInt){check(['RED','BLACK'].includes(choice),'BAD_GAMBLE_CHOICE');const v=toUnits(stake);check(v>0n,'INVALID_GAMBLE_STAKE');const won=drawIndex(draw,10000)<4750;return {choice,cardColor:won?choice:choice==='RED'?'BLACK':'RED',won,stake:fromUnits(v),payout:fromUnits(won?2n*v:0n)};}
export function bonusRewards(bet,draw=randomInt){const stake=toUnits(bet),m=[2,5,10];for(let i=m.length-1;i>0;i--){const j=drawIndex(draw,i+1);[m[i],m[j]]=[m[j],m[i]];}return m.map(x=>fromUnits(stake*BigInt(x)));}
export function publicGames(){return Object.values(MATH.games).map(g=>({
 id:g.id,name:g.name,reels:g.reels,rows:g.rows,theme:g.theme,paylines:paths(g).length,wheel:g.wheel,betLevels:g.betLevels||MATH.betLevels,
 previewReels:g.reelStrips.map(s=>[...new Set(s)]),features:{...g.features},mathVersion:g.mathVersion||MATH.mathVersion,engineVersion:ENGINE_VERSION,
 currency:MATH.currency,maxWinMultiplier:g.maxWinMultiplier,paytable:g.paytable,linePaths:paths(g),
 rules:{lineDirection:'left_to_right',minimumMatch:3,betAllocation:'total_bet_divided_by_lines',wildSymbols:['multi_hot_5_video','multi_hot_5_native'].includes(g.id)?[]:['hot_foxy_20','foxy_hot_20_native'].includes(g.id)?['fox']:['wild','super_wild'],wildReplacesScatter:false,
 scatter:['multi_hot_5_video','multi_hot_5_native','foxy_hot_20_native'].includes(g.id)?null:{trigger:3,pays:{3:2,4:10,5:50},multipliedByWheel:true,jackpotsReplaceScatterPay:true},
 settlement:{calculationDecimals:4,walletDecimals:2,rounding:'floor'},
 gamble:g.features.gambleRounds?{choices:['RED','BLACK'],winProbability:.475,winMultiplier:2,maxRounds:g.features.gambleRounds,...(g.features.gambleMaxStake?{maxStake:g.features.gambleMaxStake}:{})}:null}}));}
// Validate every game's geometry and payout inputs before accepting a request.
for(const g of Object.values(MATH.games)){
 check(g.reelStrips.length===g.reels&&g.reelStrips.every(s=>s.length>=g.rows),'INVALID_REEL_LAYOUT');
 const p=paths(g);check(p.length>0&&p.every(p=>p.length===g.reels&&p.every(r=>Number.isInteger(r)&&r>=0&&r<g.rows)),'INVALID_PAYLINES');
 check(new Set(p.map(p=>p.join(','))).size===p.length,'DUPLICATE_PAYLINE');
 check((g.betLevels||MATH.betLevels).every(b=>toUnits(b)%BigInt(p.length)===0n),'BET_SPLIT_ERROR');
}